widget.draw:
function draw(ctx, state, t) {
  var w = state.w;
  var h = state.h;
  var xv = state.x;
  function fmt(v) { return Math.round(v * 100) / 100; }
  function X(v) { return 48 + (v + 3) / 6 * 440; }
  function Y(v) { return 300 - (v + 1.2) / 4.4 * 260; }
  function geluF(u) { var inner = 0.79788456 * (u + 0.044715 * u * u * u); var e = Math.exp(2 * inner); var th = (e - 1) / (e + 1); return 0.5 * u * (1 + th); }
  function reluF(u) { if (u > 0) { return u; } return 0; }
  ctx.clearRect(0, 0, w, h);
  ctx.fillStyle = "#f6f3ec";
  ctx.fillRect(0, 0, w, h);
  ctx.strokeStyle = "#d8cfbe";
  ctx.lineWidth = 1;
  ctx.beginPath();
  ctx.moveTo(48, Y(0));
  ctx.lineTo(488, Y(0));
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(X(0), 20);
  ctx.lineTo(X(0), 300);
  ctx.stroke();
  var i = 0;
  var u = 0;
  var g = 0;
  var r = 0;
  var px = 0;
  var py = 0;
  var qx = 0;
  var qy = 0;
  ctx.strokeStyle = "#c4512c";
  ctx.lineWidth = 2;
  for (i = 0; i < 120; i++) {
    u = -3 + i / 119 * 6;
    r = reluF(u);
    px = X(u);
    py = Y(r);
    qx = X(-3 + (i + 1) / 119 * 6);
    qy = Y(reluF(-3 + (i + 1) / 119 * 6));
    if (i % 2 === 0) { ctx.beginPath(); ctx.moveTo(px, py); ctx.lineTo(qx, qy); ctx.stroke(); }
  }
  ctx.strokeStyle = "#1f4b99";
  ctx.lineWidth = 3;
  ctx.beginPath();
  for (i = 0; i <= 120; i++) {
    u = -3 + i / 120 * 6;
    g = geluF(u);
    px = X(u);
    py = Y(g);
    if (i === 0) { ctx.moveTo(px, py); } else { ctx.lineTo(px, py); }
  }
  ctx.stroke();
  var gv = geluF(xv);
  var rv = reluF(xv);
  var mx = X(xv);
  var gy = Y(gv);
  var ry = Y(rv);
  ctx.strokeStyle = "#1d1a16";
  ctx.lineWidth = 1;
  ctx.beginPath();
  ctx.moveTo(mx, 20);
  ctx.lineTo(mx, 300);
  ctx.stroke();
  ctx.fillStyle = "#1f4b99";
  ctx.beginPath();
  ctx.arc(mx, gy, 7, 0, 6.2832);
  ctx.fill();
  ctx.fillStyle = "#c4512c";
  ctx.beginPath();
  ctx.arc(mx, ry, 6, 0, 6.2832);
  ctx.fill();
  ctx.fillStyle = "#1f4b99";
  ctx.fillRect(504, 60, 12, 12);
  ctx.fillStyle = "#c4512c";
  ctx.fillRect(504, 84, 12, 12);
  ctx.font = "13px sans-serif";
  ctx.textAlign = "left";
  ctx.textBaseline = "alphabetic";
  ctx.fillStyle = "#1d1a16";
  ctx.fillText("GELU", 520, 71);
  ctx.fillText("ReLU", 520, 95);
  ctx.font = "14px sans-serif";
  ctx.fillText("x " + fmt(xv), 504, 140);
  ctx.fillStyle = "#1f4b99";
  ctx.fillText("gelu " + fmt(gv), 504, 162);
  ctx.fillStyle = "#c4512c";
  ctx.fillText("relu " + fmt(rv), 504, 184);
  ctx.fillStyle = "#5b554b";
  ctx.font = "12px sans-serif";
  ctx.fillText("neg leak", 90, 250);
  ctx.fillText("identity", 380, 130);
  if (gy > 300) { ctx.fillStyle = "#1d1a16"; ctx.fillText("clipped", mx - 20, 300); }
  if (ry > 300) { ctx.fillStyle = "#1d1a16"; ctx.fillText("clipped", mx - 20, 292); }
}
